import sympy as sp
from sympy import *
from fractions import Fraction
import math
from itertools import combinations, permutations, product
options = {0: '75', 1: '2', 2: '25', 3: '6'}

def parse_num(s):
    s = str(s).replace('$','').replace(',','').replace('−','-').replace('^','**')
    s = s.replace('√', 'sqrt')
    if s.endswith('%'):
        return sp.sympify(s[:-1]) / 100
    return sp.sympify(s)

def check_option(opt_id):
    opt_str = options[opt_id]
    try:
        val = parse_num(opt_str)
        # Check if the value is an integer
        if not val.is_integer:
            return False

        # Count odd perfect squares between 5 and 211
        count = 0
        for i in range(3, int(math.sqrt(211)) + 1):
            square = i ** 2
            if 5 < square < 211 and square % 2 != 0:
                count += 1

        return val == count
    except Exception as e:
        return False

# Check each option
for opt_id in range(4):
    if check_option(opt_id):
        print(f"OPTION_ID: {opt_id}")
        break
else:
    # If no option matches, compute the value directly
    count = 0
    for i in range(3, int(math.sqrt(211)) + 1):
        square = i ** 2
        if 5 < square < 211 and square % 2 != 0:
            count += 1
    print(f"VALUE: {count}")

