import sympy as sp
from sympy import *
from fractions import Fraction
import math
from itertools import combinations, permutations, product
options = {0: '5,5,5', 1: '4,12,12', 2: '2,2,3', 3: '2,2,4'}

def parse_num(s):
    s = str(s).replace('$','').replace(',','').replace('−','-').replace('^','**')
    s = s.replace('√', 'sqrt')
    if s.endswith('%'):
        return sp.sympify(s[:-1]) / 100
    return sp.sympify(s)

def check_triangle(a, b, c):
    # Triangle inequality: sum of any two sides > third side
    return (a + b > c) and (a + c > b) and (b + c > a)

def is_isosceles(a, b, c):
    # At least two sides equal
    return (a == b) or (a == c) or (b == c)

for opt_id, sides_str in options.items():
    parts = [parse_num(x.strip()) for x in sides_str.split(',')]
    a, b, c = parts[0], parts[1], parts[2]

    # Check if it's an isosceles triangle
    if not is_isosceles(a, b, c):
        print(f"OPTION_ID: {opt_id}")
        continue

    # Check triangle inequality
    if not check_triangle(a, b, c):
        print(f"OPTION_ID: {opt_id}")
        continue

# If no option satisfies the condition of NOT being an isosceles triangle
print("VALUE: None")

